import {products,categories,money,sourceLink,priceFor,filterProducts,validateEventDate} from './catalog.js';
import {icon} from './icons.js';
import {sections,purposes} from './sections.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved=[];try{const raw=JSON.parse(localStorage.getItem('giftco-saved')||'[]');saved=Array.isArray(raw)?raw.filter(id=>products.some(p=>p.id===id)):[];}catch{}
const params=new URLSearchParams(location.search);
const state={query:params.get('q')||'',category:categories.some(([c])=>c===params.get('category'))?params.get('category'):'전체',purpose:purposes.some(p=>p.name===params.get('purpose'))?params.get('purpose'):'',quantity:Math.max(0,Number(params.get('qty'))||0),budget:Math.max(0,Number(params.get('budget'))||0),date:params.get('date')||'',sort:'recommended',printOnly:false,savedOnly:false,saved,compare:[],expanded:false};
$('#home-content').innerHTML=sections();
function notify(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('visible'),3500);}
function track(event,detail={}){window.dispatchEvent(new CustomEvent('giftco:analytics',{detail:{event,...detail}}));}
function syncURL(){const p=new URLSearchParams();if(state.query)p.set('q',state.query);if(state.category!=='전체')p.set('category',state.category);if(state.purpose)p.set('purpose',state.purpose);if(state.quantity)p.set('qty',state.quantity);if(state.budget)p.set('budget',state.budget);if(state.date)p.set('date',state.date);history.replaceState(null,'',location.pathname+(p.size?'?'+p:'')+location.hash);}
function syncForm(){$('#query').value=state.query;$('#budget').value=String(state.budget);$('#quantity').value=String(state.quantity);$('#event-date').value=state.date;}
function card(p){const v=priceFor(p,state.quantity);const isSaved=state.saved.includes(p.id);return `<article class="product-card"><div class="product-image"><button class="product-open" data-product="${p.id}" aria-label="${esc(p.name)} 수량별 가격 보기"><img src="./assets/${p.image}" alt="${esc(p.name)}" width="280" height="280" loading="lazy"></button>${p.tag?`<span class="product-tag">${p.tag}</span>`:''}<button class="save-button ${isSaved?'is-saved':''}" data-save="${p.id}" aria-label="${esc(p.name)} 찜${isSaved?' 해제':'하기'}" aria-pressed="${isSaved}">${icon('heart',21)}</button></div><div class="product-info"><span class="product-brand">${p.brand}</span><button class="product-name" data-product="${p.id}">${esc(p.name)}</button><p class="product-price">${money(v.price)}<span>원 / ${p.unit||'개'}</span>${v.exact?'':'<small>참고</small>'}</p><p class="price-basis">${money(v.basis)}개 기준 · VAT 별도${v.exact?'':' · 단가 상담'}</p><div class="product-conditions"><span>최소 ${p.min}개</span><span>시안 확정 후 ${p.days.join('–')}일 제작</span></div><div class="product-options">${p.print?'<span>인쇄 가능</span>':''}${p.pack?'<span>선물포장 선택</span>':''}</div><div class="card-bottom"><span>No. ${p.id}</span><label><input type="checkbox" data-compare="${p.id}" ${state.compare.includes(p.id)?'checked':''}> 비교</label></div></div></article>`;}
function render(){const list=filterProducts(products,state);const active=state.query||state.purpose||state.category!=='전체'||state.budget||state.quantity||state.savedOnly||state.printOnly;
$('#product-title').textContent=state.savedOnly?'내가 찜한 선물':active?'우리 조건에 맞는 선물':'받는 분도, 준비하는 분도 만족할 선물';
$('#product-subtitle').textContent=state.date?`${state.date} 행사 준비 · 수령 가능 여부는 상담을 통해 확인해 주세요.`:'수량을 선택하면 해당 수량의 기본 상품 단가로 비교할 수 있어요.';
$('#result-count').innerHTML=`<strong>${list.length}</strong>개 상품${state.quantity?` · ${money(state.quantity)}개 주문 기준`:' · 최소 주문 수량 기준'}`;
$('#product-grid').innerHTML=list.length?list.slice(0,state.expanded||active?100:5).map(card).join(''):`<div class="empty-state">${icon('search',38)}<h3>조건에 맞는 상품이 없어요</h3><p>예산이나 수량을 조정하거나 기프트코 전체 상품에서 찾아보세요.</p><div><button class="button primary" data-action="reset">조건 초기화</button><a class="button outline" href="https://stage.neordinary.xyz/search?q=${encodeURIComponent(state.query||(state.category==='전체'?'':state.category))}" target="_blank" rel="noopener">기프트코에서 찾기 ↗</a></div></div>`;
$('#show-more').hidden=!!active||list.length<=5||state.expanded;
const chips=[state.query&&['query',`검색: ${state.query}`],state.purpose&&['purpose',state.purpose],state.category!=='전체'&&['category',state.category],state.budget&&['budget',`${money(state.budget)}원 이하`],state.quantity&&['quantity',`${money(state.quantity)}개`],state.savedOnly&&['savedOnly','찜한 상품']].filter(Boolean);
$('#active-filters').innerHTML=chips.length?chips.map(([key,label])=>`<button data-remove="${key}" aria-label="${esc(label)} 조건 해제">${esc(label)} <span>×</span></button>`).join('')+'<button class="clear-filters" data-action="reset">초기화</button>':'';
document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.tab===state.category));document.querySelectorAll('[data-purpose]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.purpose===state.purpose));$('#saved-count').textContent=state.saved.length;$('#print-only').checked=state.printOnly;$('#sort').value=state.sort;syncURL();renderCompareBar();}
function jump(){render();$('#products').scrollIntoView({behavior:'smooth',block:'start'});}
function reset(){Object.assign(state,{query:'',category:'전체',purpose:'',quantity:0,budget:0,date:'',savedOnly:false,printOnly:false,sort:'recommended',expanded:false});syncForm();jump();}
function save(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];try{localStorage.setItem('giftco-saved',JSON.stringify(state.saved));}catch{notify('저장 공간을 사용할 수 없어 이번 방문에서만 보관합니다.');}render();track('save_product',{productId:id,saved:state.saved.includes(id)});}
let previousFocus;
function closeDialog(){const d=$('dialog');if(d)d.close();}
function openDialog(title,body,wide=false){const active=document.activeElement;const returnFocus=active?.closest('dialog')?previousFocus:active;closeDialog();previousFocus=returnFocus;$('#overlay-root').innerHTML=`<dialog class="dialog ${wide?'dialog-wide':''}" aria-labelledby="dialog-title"><div class="dialog-header"><h2 id="dialog-title">${title}</h2><button data-action="close" class="dialog-close" aria-label="닫기">${icon('close',22)}</button></div><div class="dialog-body">${body}</div></dialog>`;const d=$('dialog');d.showModal();document.body.classList.add('modal-open');d.addEventListener('close',()=>{d.remove();if(!document.querySelector('dialog[open]')){document.body.classList.remove('modal-open');if(returnFocus?.isConnected)returnFocus.focus();}});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});}
function openProduct(id){const p=products.find(p=>p.id===id);if(!p)return;const q=Math.max(state.quantity||p.min,p.min);openDialog('수량별 가격·옵션 확인',`<div class="detail-layout"><div class="detail-image"><img src="./assets/${p.image}" alt="${esc(p.name)}" width="420" height="420"></div><div class="detail-info"><span class="product-brand">${p.brand} · No. ${p.id}</span><h3>${p.name}</h3><p class="detail-spec">${p.detail}</p><div class="detail-badges"><span>최소 ${p.min}개</span><span>시안 확정 후 ${p.days.join('–')}일 제작</span></div><label class="quantity-field">주문 수량 <input type="number" id="detail-quantity" min="${p.min}" step="1" value="${q}" data-id="${id}"> 개</label><div id="detail-price" aria-live="polite"></div><p class="detail-note">VAT·인쇄·포장·배송비 별도. 제작 기간은 영업일 기준이며 수령일은 별도 확인이 필요합니다.</p><dl class="detail-options"><dt>색상</dt><dd>${p.colors}</dd><dt>인쇄</dt><dd>${p.print?'상품 상세에서 인쇄 방식 선택':'스티커 제작 옵션 확인'}</dd><dt>포장</dt><dd>${p.pack?'선물포장 옵션 선택 가능':'상세에서 케이스·구성 확인'}</dd></dl><a class="button primary full" href="${sourceLink(id)}" target="_blank" rel="noopener" data-purchase="${id}">옵션 선택·구매하기 ${icon('arrow',18)}</a><p class="external-note">기프트코 상품 상세에서 최신 가격을 확인하고 주문합니다.</p><div class="detail-secondary"><button data-consult-product="${id}">배송 일정 상담</button><button data-save="${id}">${state.saved.includes(id)?'찜 해제':'찜하기'}</button></div></div></div><div class="price-table-wrapper"><h3>수량별 기본 단가 <small>VAT 별도</small></h3><div class="table-scroll"><table><thead><tr><th scope="col">수량</th>${p.tiers.map(([n])=>`<th scope="col">${money(n)}개</th>`).join('')}</tr></thead><tbody><tr><th scope="row">${p.unit||'개'}당 가격</th>${p.tiers.map(([,v])=>`<td>${money(v)}원</td>`).join('')}</tr></tbody></table></div></div>`,true);updatePrice(p,q);track('view_product',{productId:id});}
function updatePrice(p,q){const n=Number(q);if(!Number.isInteger(n)||n<p.min||n>1000000){$('#detail-price').innerHTML=`<p class="form-error">${p.min}개 이상의 수량을 입력해 주세요. 대량 주문은 상담으로 확인하세요.</p>`;return;}const v=priceFor(p,n);$('#detail-price').innerHTML=`<div class="detail-unit">${v.exact?'기본 상품 단가':`${money(v.basis)}개 구간 참고 단가`}<strong>${money(v.price)}원 / ${p.unit||'개'}</strong></div><div class="detail-total"><span>${v.exact?'상품 금액':'참고 상품 금액'}</span><strong>${money(v.price*n)}<small>원</small></strong></div>${v.exact?'':'<p class="estimate-note">입력 수량의 확정 단가가 아닙니다. 정확한 견적은 상담해 주세요.</p>'}`;}
function renderCompareBar(){const el=$('#compare-bar');el.hidden=!state.compare.length;document.body.classList.toggle('has-compare',state.compare.length>0);if(!state.compare.length)return;el.innerHTML=`<div><strong>${state.compare.length}개 상품 선택</strong><span>가격·수량·제작 조건을 한눈에</span></div><button data-action="clear-compare" class="compare-clear">선택 해제</button><button data-action="compare" class="button primary" ${state.compare.length<2?'disabled':''}>비교하기 ${icon('compare',18)}</button>`;}
function compare(){if(state.compare.length<2)return;const list=state.compare.map(id=>products.find(p=>p.id===id));const rows=[['상품 단가',p=>{const v=priceFor(p,state.quantity);return v?`<strong>${money(v.price)}원</strong><small>${money(v.basis)}개 기준${v.exact?'':' · 참고'}</small>`:'선택 수량 주문 불가';}],['최소 주문 수량',p=>`${p.min}개`],['제작 기간',p=>`시안 확정 후 ${p.days.join('–')}일`],['인쇄',p=>p.print?'가능':'스티커 옵션 확인'],['선물포장',p=>p.pack?'선택 가능':'상세 확인'],['다음 단계',p=>`<button class="button outline" data-product="${p.id}">가격·옵션 보기</button>`]];openDialog('선물 후보 비교',`<p class="dialog-intro">${state.quantity?`${money(state.quantity)}개 주문`:'각 상품의 최소 수량'} 기준 · VAT·옵션·배송비 별도</p><div class="table-scroll compare-table"><table><thead><tr><th scope="col">비교 항목</th>${list.map(p=>`<th scope="col"><img src="./assets/${p.image}" alt="" width="160" height="160">${p.name}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th scope="row">${label}</th>${list.map(p=>`<td>${fn(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,true);track('compare_products',{products:state.compare});}
function policy(){openDialog('기프트코 책임배송 약속',`<div class="policy-lead">${icon('shield',40)}<h3>약속한 날짜까지.<br>행사 기한을 못 맞추면 책임집니다.</h3></div><p class="dialog-intro">책임배송은 행사에 필요한 날짜를 확인하고, 고객과 약속한 배송 기한을 책임지는 기프트코의 약속입니다.</p><div class="policy-list"><h3>주문 전에 함께 확인해 주세요</h3><ul><li><strong>고객 수령일:</strong> 출고일과 실제 도착일을 구분해 확인합니다.</li><li><strong>제작 조건:</strong> 상품·수량·인쇄·포장·시안 확정 일정을 확인합니다.</li><li><strong>책임 내용:</strong> 기한 미준수 시 적용되는 책임 범위와 처리 방법을 확인합니다.</li></ul></div><div class="notice-panel">구체적인 보상 방식과 적용 조건은 주문별 안내를 확인해 주세요. 이 화면에서 배송일이나 보상 금액을 확정하지 않습니다.</div><div class="dialog-actions"><a class="button primary" href="https://stage.neordinary.xyz/responsible-delivery" target="_blank" rel="noopener">책임배송 공식 안내 ↗</a><button class="button outline" data-action="consult">내 행사 일정 상담</button></div>`);track('view_delivery_policy');}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function consult(id){const p=products.find(p=>p.id===Number(id));openDialog('행사 일정·단체주문 상담',`<p class="dialog-intro">필요한 조건을 정리하면 상담이 빨라집니다.<br>개인 연락처 입력 없이 상담 내용을 준비할 수 있어요.</p><form id="consult-form"><div class="consult-grid"><label>행사 목적<select name="purpose">${['기관 행사','임직원 선물','창립·감사 선물','웰컴키트','기타'].map(x=>`<option ${x===state.purpose?'selected':''}>${x}</option>`).join('')}</select></label><label>필요 수량<input name="quantity" type="number" min="1" max="1000000" step="1" value="${state.quantity||100}" required></label><label>개당 예산 (원)<input name="budget" type="number" min="0" step="1" placeholder="미정이면 비워 주세요" value="${state.budget||''}"></label><label>행사 예정일<input name="date" type="date" value="${esc(state.date)}" min="${localDate()}" required></label></div><label class="consult-message">관심 상품·인쇄·포장 등<textarea name="message" rows="3" maxlength="1500" placeholder="예: 로고 인쇄, 개별 포장이 필요해요.">${p?esc(`${p.name} (상품번호 ${p.id})`):''}</textarea></label><p class="form-error" id="consult-error" role="alert"></p><button class="button primary full" type="submit">상담 내용 준비하기</button><p class="external-note">자동 접수되지 않습니다. 다음 단계에서 이메일 또는 전화로 전달하세요.</p></form><div class="consult-contact"><a href="tel:16442119">${icon('phone',20)} 1644-2119</a><span>평일 09:00–18:00 · 점심 12:00–13:00</span></div>`);$('#consult-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(!validateEventDate(f.get('date'))){$('#consult-error').textContent='행사 예정일은 오늘 이후로 선택해 주세요.';return;}const text=`[기프트코 단체주문 상담]\n행사 목적: ${f.get('purpose')}\n필요 수량: ${f.get('quantity')}개\n개당 예산: ${f.get('budget')?money(Number(f.get('budget')))+'원':'미정'}\n행사 예정일: ${f.get('date')}\n요청 사항: ${f.get('message')||'없음'}\n\n수령 가능 날짜와 책임배송 적용 조건을 안내해 주세요.`;consultSummary(text);track('prepare_inquiry',{purpose:f.get('purpose')});});}
function consultSummary(text){openDialog('상담 내용이 준비되었습니다',`<p class="dialog-intro">아래 내용을 전달하면 담당자가 상품과 배송 일정을 확인할 수 있습니다.</p><pre class="inquiry-summary">${esc(text)}</pre><div class="dialog-actions"><a class="button primary" href="mailto:gift@gift.co.kr?subject=${encodeURIComponent('행사 일정·단체주문 상담')}&body=${encodeURIComponent(text)}">이메일 앱에서 보내기</a><button id="copy-summary" class="button outline">내용 복사</button></div><p class="external-note">이메일 앱에서 보내기를 완료해 주세요. 현재 접수되거나 배송이 확정된 상태는 아닙니다.</p><a class="phone-fallback" href="tel:16442119">전화 상담 1644-2119</a>`);$('#copy-summary').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(text);notify('상담 내용을 복사했습니다.');}catch{notify('복사할 수 없습니다. 위 내용을 선택해 복사해 주세요.');}});}
function menu(){openDialog('상품 카테고리',`<div class="menu-categories">${categories.map(([n,img])=>`<button data-category="${n}">${img?`<img src="./assets/${img}" alt="" width="48" height="48">`:icon('gift',30)}<span>${n}</span></button>`).join('')}</div><h3 class="menu-heading">행사·목적별</h3><div class="menu-purposes">${purposes.map(p=>`<button data-purpose="${p.name}">${icon(p.icon,20)}${p.name}</button>`).join('')}</div><a class="button outline full" href="https://stage.neordinary.xyz/" target="_blank" rel="noopener">기프트코 전체 카테고리 보기 ↗</a>`);}
function guide(n){const t=[['예산과 수량부터 확인하세요','수량에 따라 개당 가격이 달라집니다. 필요한 수량을 정하고, 상품 금액에 부가세·인쇄·포장·배송비가 더해지는지 확인하세요.','상품 카드에서 수량별 가격표를 열어 비교할 수 있습니다.'],['인쇄와 포장을 확인하세요','로고가 들어갈 위치와 크기, 색상 수, 인쇄 방식을 확인해 주세요. 선물포장과 케이스가 기본 구성인지 추가 옵션인지도 중요합니다.','상품마다 지원 옵션이 다르므로 상세에서 선택해 주세요.'],['수령일을 확인하세요','제작 기간은 시안 확정 후 기준입니다. 행사일, 배송지, 수량과 인쇄·포장 조건을 알려주고 실제 수령 가능한 날짜를 확인하세요.','배송 약속과 기한 미준수 시 책임 범위를 주문 전에 확인해 주세요.']][n];openDialog(t[0],`<div class="guide-dialog-icon">${icon(['gift','bag','calendar'][n],36)}</div><p class="dialog-intro">${t[1]}</p><div class="notice-panel">${t[2]}</div><div class="dialog-actions"><button class="button primary" data-action="${n===2?'consult':'back-to-products'}">${n===2?'배송 일정 상담':'상품 비교하기'}</button><button class="button outline" data-action="close">확인</button></div>`);}
function video(){openDialog('슈카와 함께하는 기프트코',`<img class="campaign-full" src="./assets/shuka-campaign.jpg" alt="슈카의 판촉물 구매 가이드"><p class="dialog-intro">기프트코의 공식 영상과 상품 이야기를 만나보세요.</p><a class="button primary full" href="https://www.youtube.com/@giftcokr/shorts" target="_blank" rel="noopener">기프트코 공식 영상 보기 ↗</a>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;
if(b.dataset.category){Object.assign(state,{category:b.dataset.category,query:'',savedOnly:false,expanded:true});closeDialog();syncForm();jump();track('select_category',{category:state.category});}
if(b.dataset.tab){state.category=b.dataset.tab;state.expanded=true;render();}
if(b.dataset.purpose){Object.assign(state,{purpose:b.dataset.purpose,category:'전체',query:'',savedOnly:false,expanded:true});closeDialog();syncForm();jump();track('select_purpose',{purpose:state.purpose});}
if(b.dataset.product)openProduct(Number(b.dataset.product));if(b.dataset.save){save(Number(b.dataset.save));if(b.closest('dialog'))b.textContent=state.saved.includes(Number(b.dataset.save))?'찜 해제':'찜하기';}
if(b.dataset.remove){const k=b.dataset.remove;state[k]=k==='category'?'전체':['quantity','budget'].includes(k)?0:k==='savedOnly'?false:'';syncForm();render();}
if(b.dataset.consultProduct)consult(b.dataset.consultProduct);if(b.dataset.guide!==undefined)guide(Number(b.dataset.guide));if(b.dataset.purchase)track('purchase_handoff',{productId:Number(b.dataset.purchase)});
const a=b.dataset.action;if(a==='close')closeDialog();if(a==='menu')menu();if(a==='policy')policy();if(a==='consult')consult();if(a==='reset')reset();if(a==='video')video();if(a==='saved'){closeDialog();Object.assign(state,{savedOnly:true,query:'',category:'전체',purpose:'',budget:0,quantity:0,printOnly:false,expanded:true});syncForm();jump();}if(a==='more'){state.expanded=true;render();}if(a==='compare')compare();if(a==='clear-compare'){state.compare=[];render();}if(a==='back-to-products'){closeDialog();$('#products').scrollIntoView();}});
document.addEventListener('change',e=>{if(e.target.dataset.compare){const id=Number(e.target.dataset.compare);if(e.target.checked){if(state.compare.length===3){e.target.checked=false;notify('한 번에 3개 상품까지 비교할 수 있어요.');return;}state.compare.push(id);}else state.compare=state.compare.filter(x=>x!==id);renderCompareBar();}if(e.target.id==='sort'){state.sort=e.target.value;render();}if(e.target.id==='print-only'){state.printOnly=e.target.checked;render();}});
document.addEventListener('input',e=>{if(e.target.id==='detail-quantity')updatePrice(products.find(p=>p.id===Number(e.target.dataset.id)),e.target.value);});
$('#finder-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(!validateEventDate(f.get('date'))){$('#event-date').setCustomValidity('행사 예정일은 오늘 이후로 선택해 주세요.');$('#event-date').reportValidity();return;}Object.assign(state,{query:String(f.get('query')).trim(),budget:Number(f.get('budget')),quantity:Number(f.get('quantity')),date:String(f.get('date')),savedOnly:false,expanded:true});jump();track('search',{query:state.query,quantity:state.quantity,budget:state.budget});});
$('#event-date').min=localDate();$('#event-date').addEventListener('input',()=>$('#event-date').setCustomValidity(''));
$('#header-search').addEventListener('submit',e=>{e.preventDefault();Object.assign(state,{query:String(new FormData(e.currentTarget).get('q')).trim(),category:'전체',purpose:'',savedOnly:false,expanded:true});syncForm();jump();});
$('.header-search button').innerHTML=icon('search',20);$('.search-field>span').innerHTML=icon('search',23);$('.mobile-menu').innerHTML=icon('menu',24);$('.cart-link').innerHTML=icon('bag',20)+'<span>장바구니</span>';
document.querySelectorAll('.mobile-bottom>a,.mobile-bottom>button').forEach((el,i)=>{el.innerHTML=icon(['home','menu','search','heart','phone'][i],22)+`<span>${['홈','카테고리','검색','찜','상담'][i]}</span>`;});
$('.hero-art').insertAdjacentHTML('beforeend',`<div class="delivery-ticket"><span>${icon('shield',26)}</span><div><strong>선물은 제때, 마음은 제대로.</strong><small>기프트코 책임배송</small></div></div>`);
syncForm();render();
// Progressive enhancement: operate only on this page's local catalog, never place orders.
if(navigator.modelContext?.registerTool){try{navigator.modelContext.registerTool({name:'giftco_search_products',description:'Filter the displayed Giftco catalog. Prices exclude VAT, options and shipping; arrival dates require consultation.',inputSchema:{type:'object',properties:{query:{type:'string'},quantity:{type:'integer',minimum:0},budget:{type:'integer',minimum:0}}},execute:async(input)=>{Object.assign(state,{query:input.query||'',quantity:input.quantity||0,budget:input.budget||0,category:'전체',purpose:'',savedOnly:false,expanded:true});syncForm();jump();return{content:[{type:'text',text:JSON.stringify(filterProducts(products,state).map(p=>({id:p.id,name:p.name,price:priceFor(p,state.quantity),source:sourceLink(p.id)})))}]};}});}catch{/* Unsupported experimental implementation; standard UI stays available. */}}
